import SwiftUI

// MARK: - 水墨背景线：六套主题
//
// 数据直接从 HTML 试验稿导出，坐标统一是 390 × 844 的屏幕空间。
// 每套拆成远 / 中 / 近三层，滚动时按不同速率平移。

enum InkLineTheme: String, CaseIterable, Identifiable {
    case ridge, contour, dryBrush, ripple, meridian, singleStroke

    var id: String { rawValue }

    var title: String {
        switch self {
        case .ridge: return "远山"
        case .contour: return "等高线"
        case .dryBrush: return "飞白"
        case .ripple: return "涟漪"
        case .meridian: return "经纬"
        case .singleStroke: return "一笔"
        }
    }

    var caption: String {
        switch self {
        case .ridge: return "横向起伏，三层粗细拉开远近"
        case .contour: return "地形图的层层递进，密而不乱"
        case .dryBrush: return "干笔横扫，边缘有毛口"
        case .ripple: return "画面外荡开的同心水波"
        case .meridian: return "透视线收向远处的一点"
        case .singleStroke: return "一道重墨，一道回声"
        }
    }
}

/// 线的笔色：和 HTML 里的渐变一一对应
enum InkStroke {
    case far, mid, near, faint, vert, ink
    case solid(String)

    /// 竖直线用从下往上的渐变
    var isVertical: Bool {
        if case .vert = self { return true }
        return false
    }

    func stops(dark: Bool) -> [Gradient.Stop] {
        let base = dark
            ? Color(red: 0.87, green: 0.86, blue: 0.84)
            : Color(red: 0.102, green: 0.110, blue: 0.122)

        func s(_ p: Double, _ o: Double) -> Gradient.Stop {
            Gradient.Stop(color: base.opacity(o), location: p)
        }

        switch self {
        case .far:
            return [s(0, 0), s(0.22, 0.07), s(0.70, 0.05), s(1, 0)]
        case .mid:
            return [s(0, 0), s(0.18, 0.13), s(0.55, 0.17), s(0.86, 0.08), s(1, 0)]
        case .near:
            return [s(0, 0), s(0.30, 0.21), s(0.68, 0.15), s(1, 0)]
        case .faint:
            return [s(0, 0), s(0.30, 0.055), s(0.72, 0.04), s(1, 0)]
        case .vert:
            return [s(0, 0.24), s(0.42, 0.15), s(1, 0)]
        case .ink:
            return [s(0, 0), s(0.30, 0.34), s(0.66, 0.23), s(1, 0)]
        case .solid(let hex):
            let c = Color(hex: hex)
            return [Gradient.Stop(color: c.opacity(0), location: 0),
                    Gradient.Stop(color: c, location: 0.35),
                    Gradient.Stop(color: c, location: 0.7),
                    Gradient.Stop(color: c.opacity(0), location: 1)]
        }
    }
}

struct InkLine: Identifiable {
    let id = UUID()
    let path: Path
    let stroke: InkStroke
    let width: CGFloat
    let opacity: Double
    let blur: CGFloat
    let dash: [CGFloat]

    init(_ d: String, _ s: InkStroke, _ w: CGFloat, _ o: Double = 1,
         blur b: CGFloat = 0, dash: [CGFloat] = []) {
        self.path = SVGPath.parse(d)
        self.stroke = s
        self.width = w
        self.opacity = o
        self.blur = b
        self.dash = dash
    }

    init(rect: CGRect, s: InkStroke, w: CGFloat, o: Double = 1) {
        self.path = Path(ellipseIn: rect)
        self.stroke = s
        self.width = w
        self.opacity = o
        self.blur = 0
        self.dash = []
    }
}

