// MARK: - 极简 SVG path 解析（只覆盖 M / L / C / Q / Z，全为绝对坐标）

enum SVGPath {
    static func parse(_ d: String) -> Path {
        var path = Path()
        var numbers: [CGFloat] = []
        var command: Character = "M"
        var cursor = CGPoint.zero
        var start = CGPoint.zero

        func flush() {
            defer { numbers.removeAll() }
            switch command {
            case "M":
                guard numbers.count >= 2 else { return }
                cursor = CGPoint(x: numbers[0], y: numbers[1])
                start = cursor
                path.move(to: cursor)
            case "L":
                var k = 0
                while k + 1 < numbers.count {
                    cursor = CGPoint(x: numbers[k], y: numbers[k + 1])
                    path.addLine(to: cursor)
                    k += 2
                }
            case "C":
                var k = 0
                while k + 5 < numbers.count {
                    let c1 = CGPoint(x: numbers[k], y: numbers[k + 1])
                    let c2 = CGPoint(x: numbers[k + 2], y: numbers[k + 3])
                    let end = CGPoint(x: numbers[k + 4], y: numbers[k + 5])
                    path.addCurve(to: end, control1: c1, control2: c2)
                    cursor = end
                    k += 6
                }
            case "Q":
                var k = 0
                while k + 3 < numbers.count {
                    let c = CGPoint(x: numbers[k], y: numbers[k + 1])
                    let end = CGPoint(x: numbers[k + 2], y: numbers[k + 3])
                    path.addQuadCurve(to: end, control: c)
                    cursor = end
                    k += 4
                }
            case "Z":
                path.closeSubpath()
                cursor = start
            default:
                break
            }
        }

        var i = d.startIndex
        while i < d.endIndex {
            let ch = d[i]
            if ch.isLetter {
                flush()
                command = ch
                if ch == "Z" { flush() }
                i = d.index(after: i)
            } else if ch == "," || ch == " " {
                i = d.index(after: i)
            } else {
                var j = i
                while j < d.endIndex, !d[j].isLetter, d[j] != ",", d[j] != " " {
                    j = d.index(after: j)
                }
                if let v = Double(d[i..<j]) { numbers.append(CGFloat(v)) }
                i = j
            }
        }
        flush()
        return path
    }
}

extension Color {
    init(hex: String) {
        var s = hex.trimmingCharacters(in: CharacterSet(charactersIn: "#"))
        if s.count == 3 { s = s.map { "\($0)\($0)" }.joined() }
        var v: UInt64 = 0
        Scanner(string: s).scanHexInt64(&v)
        self.init(
            red: Double((v >> 16) & 0xFF) / 255,
            green: Double((v >> 8) & 0xFF) / 255,
            blue: Double(v & 0xFF) / 255
        )
    }
}
